export function imageAttributes(attrs){
 const variants=VARIANTS[attrs.src];if(!variants||attrs.srcset)return attrs;
 return {...attrs,src:variants[0].src,srcset:variants.map(v=>v.src+' '+v.width+'w').join(', '),sizes:attrs.loading==='lazy'?'(max-width: 650px) 90vw, 480px':'(max-width: 650px) 95vw, 680px',decoding:'async'};
}
export function backgroundAsset(src){
 const variants=VARIANTS[src];if(!variants||!matchMedia('(max-width: 650px)').matches)return src;
 return variants.find(v=>v.width>=768)?.src||src;
}
